{id: "canvas_Row1", smiles: "CCCCCCCCCCCC1=C(O)C(=O)C=C(OC)C1=O" },
{id: "canvas_Row2", smiles: "O=c1c(O)c(-c2ccc(O)c(O)c2)oc2cc(O)cc(O)c12" },
{id: "canvas_Row3", smiles: "CCCCCCCCCCCC1=C(O)C(=O)C=C(OCC)C1=O" },
